package edu.campusconnect.security;
import io.jsonwebtoken.*;import io.jsonwebtoken.security.Keys;import org.springframework.stereotype.Service;import org.springframework.beans.factory.annotation.Value;import javax.crypto.SecretKey;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;
@Service public class JwtService {private final SecretKey key;public JwtService(@Value("${app.jwt-secret}") String secret){if(secret.getBytes(StandardCharsets.UTF_8).length<32)throw new IllegalArgumentException("JWT secret must be >=32 bytes");key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));}public String issue(UUID id){return Jwts.builder().subject(id.toString()).issuedAt(new Date()).expiration(Date.from(Instant.now().plusSeconds(900))).signWith(key).compact();}public UUID verify(String token){return UUID.fromString(Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload().getSubject());}}
